fn hash(seed: i32) -> i32 {
    let mut h: i32 = seed * 747796405 + 2891336453;
    h = (h >> 16) ^ h;
    if h < 0 { h = 0 - h; }
    h
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, -20);
        host::display::state_set(2, -240);
        host::display::state_set(3, 1);
        host::display::state_set(4, 2);
        host::display::state_set(7, 0);
        host::display::state_set(8, 0);
        let mut b: i32 = 0;
        while b < 4 {
            host::display::state_set(20 + b, 1);
            b = b + 1;
        }
    }
    let down: i32 = host::display::pointer_down();
    let tap: bool = down == 1 && host::display::state_get(9) == 0;
    host::display::state_set(9, down);
    if host::display::state_get(8) == 1 {
        host::display::clear(0x180808);
        host::display::draw_string(120, 180, "CITY FELL", 0xff4040, 4);
        host::display::draw_string(120, 250, "INTERCEPTED", 0x808080, 2);
        host::display::draw_number(340, 244, host::display::state_get(7), 0xffffff, 3);
        host::display::draw_string(130, 320, "TAP TO REBUILD", 0x808080, 2);
        if tap { host::display::state_set(0, 0); }
    } else {
        host::display::clear(0x060612);
        let px: i32 = host::display::pointer_x();
        let py: i32 = host::display::pointer_y();
        let mut i: i32 = 0;
        while i < 2 {
            let rnd: i32 = host::display::state_get(3 + i);
            let colm: i32 = hash(rnd * 19 + i) % 4;
            let mx: i32 = 30 + colm * 120 + 40;
            let spd: i32 = 2 + hash(rnd * 7 + i) % 3;
            let mut my: i32 = host::display::state_get(1 + i);
            my = my + spd;
            let mut gone: i32 = 0;
            if tap {
                let dx: i32 = px - mx;
                let dy: i32 = py - my;
                if dx * dx + dy * dy <= 676 {
                    gone = 1;
                    host::display::state_set(7, host::display::state_get(7) + 1);
                }
            }
            if my > h - 70 && gone == 0 {
                host::display::state_set(20 + colm, 0);
                gone = 1;
            }
            if gone == 1 {
                host::display::state_set(3 + i, rnd + 1);
                my = -20 - hash(rnd * 13 + i) % 160;
            }
            host::display::state_set(1 + i, my);
            host::display::fill_rect(mx - 4, my - 26, 8, 16, 0x883311);
            host::display::fill_rect(mx - 10, my - 10, 20, 20, 0xff7722);
            host::display::fill_rect(mx - 5, my - 5, 10, 10, 0xffcc44);
            i = i + 1;
        }
        let mut alive: i32 = 0;
        let mut b2: i32 = 0;
        while b2 < 4 {
            let bx: i32 = 30 + b2 * 120;
            if host::display::state_get(20 + b2) == 1 {
                alive = alive + 1;
                host::display::fill_rect(bx, h - 70, 80, 70, 0x33415a);
                let mut wy: i32 = 0;
                while wy < 3 {
                    host::display::fill_rect(bx + 12, h - 60 + wy * 20, 12, 10, 0xffe080);
                    host::display::fill_rect(bx + 54, h - 60 + wy * 20, 12, 10, 0xffe080);
                    wy = wy + 1;
                }
            } else {
                host::display::fill_rect(bx, h - 24, 80, 24, 0x20242c);
            }
            b2 = b2 + 1;
        }
        if alive == 0 { host::display::state_set(8, 1); }
        host::display::draw_string(8, 8, "TAP THE METEORS", 0x808080, 2);
        host::display::draw_number(w - 70, 8, host::display::state_get(7), 0x00ff88, 3);
    }
    host::display::present();
}
